'use client';

import { useEffect, useId, useRef, useState, type KeyboardEvent } from 'react';
import './command-palette.css';

export interface Command {
  id: string;
  label: string;
  hint?: string;
}

export interface CommandPaletteProps {
  commands: Command[];
  onRun: (command: Command) => void;
  /** Text on the opening button. */
  label?: string;
  /** Listen for Ctrl+K / ⌘K while mounted. */
  shortcut?: boolean;
  className?: string;
}

/**
 * A searchable command list in a modal dialog. Open it with the button or
 * Ctrl+K / ⌘K, move with the arrow keys, run with Enter. Escape closes it,
 * and focus goes back to wherever it was before.
 */
export function CommandPalette({
  commands,
  onRun,
  label = 'Commands',
  shortcut = true,
  className = '',
}: CommandPaletteProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const opener = useRef<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const id = useId();

  const results = commands.filter((c) =>
    c.label.toLowerCase().includes(query.trim().toLowerCase())
  );
  const current = results[Math.min(active, results.length - 1)];

  useEffect(() => {
    const el = dialog.current;
    if (!el) return;
    if (open && !el.open) {
      opener.current = document.activeElement as HTMLElement | null;
      el.showModal();
      input.current?.focus();
    } else if (!open && el.open) {
      el.close();
      // Only now is the rest of the page focusable again.
      opener.current?.focus();
    }
  }, [open]);

  useEffect(() => {
    if (!shortcut) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key.toLowerCase() === 'k' && (event.ctrlKey || event.metaKey)) {
        event.preventDefault();
        setOpen(true);
      }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [shortcut]);

  const finish = (command?: Command) => {
    setOpen(false);
    setQuery('');
    setActive(0);
    if (command) onRun(command);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      const step = event.key === 'ArrowDown' ? 1 : -1;
      setActive((i) =>
        results.length ? (i + step + results.length) % results.length : 0
      );
    } else if (event.key === 'Enter' && current) {
      event.preventDefault();
      finish(current);
    }
  };

  return (
    <>
      <button
        type='button'
        className={`mg-cmdk__open ${className}`}
        onClick={() => setOpen(true)}
      >
        {label}
        {shortcut ? <kbd aria-hidden='true'>Ctrl K</kbd> : null}
      </button>
      <dialog
        ref={dialog}
        className='mg-cmdk'
        aria-label={label}
        onClose={() => {
          // Escape closed the dialog natively; sync state and restore focus.
          if (!open) return;
          finish();
          opener.current?.focus();
        }}
        onClick={(event) => {
          if (event.target === event.currentTarget) finish();
        }}
      >
        <div className='mg-cmdk__panel'>
          <input
            ref={input}
            className='mg-cmdk__input'
            role='combobox'
            aria-expanded='true'
            aria-controls={`${id}-list`}
            aria-activedescendant={current ? `${id}-${current.id}` : undefined}
            aria-label='Type a command'
            placeholder='Type a command…'
            value={query}
            onChange={(event) => {
              setQuery(event.target.value);
              setActive(0);
            }}
            onKeyDown={onKeyDown}
          />
          <ul
            id={`${id}-list`}
            role='listbox'
            aria-label='Commands'
            className='mg-cmdk__list'
          >
            {results.map((command) => (
              <li
                key={command.id}
                id={`${id}-${command.id}`}
                role='option'
                aria-selected={command === current}
                className='mg-cmdk__option'
                onPointerMove={() => setActive(results.indexOf(command))}
                onClick={() => finish(command)}
              >
                <span>{command.label}</span>
                {command.hint ? (
                  <span className='mg-cmdk__hint'>{command.hint}</span>
                ) : null}
              </li>
            ))}
          </ul>
          {results.length === 0 ? (
            <p className='mg-cmdk__empty'>No command matches “{query}”.</p>
          ) : null}
          <p className='mg-cmdk__keys' aria-hidden='true'>
            ↑↓ to move · Enter to run · Esc to close
          </p>
        </div>
      </dialog>
    </>
  );
}

.mg-cmdk__open {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 10px;
  background: #121212;
  color: var(--mg-text, #ffffff);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-cmdk__open:focus-visible {
  outline: 3px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

.mg-cmdk__open kbd {
  padding: 1px 6px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 5px;
  background: var(--mg-raised, #1b1b1b);
  color: #b8b8b8;
  font:
    11px ui-monospace,
    monospace;
}

.mg-cmdk {
  width: min(460px, calc(100% - 32px));
  margin: 12vh auto auto;
  padding: 0;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 14px;
  background: #121212;
  box-shadow: 0 30px 60px -20px rgba(0, 0, 0, 0.55);
  color: var(--mg-text, #ffffff);
}

.mg-cmdk[open] {
  animation: mg-cmdk-in 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-cmdk::backdrop {
  background: rgba(0, 0, 0, 0.4);
  animation: mg-cmdk-fade 200ms ease;
}

.mg-cmdk__input {
  width: 100%;
  height: 52px;
  padding: 0 16px;
  border: 0;
  border-bottom: 1px solid var(--mg-line, #303030);
  background: none;
  color: inherit;
  font: inherit;
  font-size: 16px;
}

.mg-cmdk__input:focus {
  outline: none;
  box-shadow: inset 0 -2px 0 var(--mg-accent-text, #dce9f7);
}

.mg-cmdk__list {
  max-height: 260px;
  margin: 0;
  padding: 6px;
  overflow: auto;
  list-style: none;
}

.mg-cmdk__option {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 8px;
  cursor: pointer;
}

.mg-cmdk__option[aria-selected='true'] {
  background: var(--mg-accent, #eaf2fb);
  color: #080808;
}

.mg-cmdk__hint {
  opacity: 0.7;
  font-size: 13px;
}

.mg-cmdk__empty,
.mg-cmdk__keys {
  margin: 0;
  padding: 10px 16px;
  color: #b8b8b8;
  font-size: 13px;
}

.mg-cmdk__keys {
  border-top: 1px solid var(--mg-line, #303030);
  font-size: 12px;
}

@keyframes mg-cmdk-in {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.98);
  }
}

@keyframes mg-cmdk-fade {
  from {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-cmdk[open],
  .mg-cmdk::backdrop {
    animation: none;
  }
}
